/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `prescription_item_before_delete` BEFORE DELETE ON `prescription_item` FOR EACH ROW BEGIN
    IF (SELECT COUNT(*) FROM prescription_item WHERE prescription_id = OLD.prescription_id) <= 1 THEN
